import "server-only";
import { embed, apiKeyEnvName, sha256Hex, canonical, type ModelRoute } from "@pg/ai";
import { createServiceClient } from "@/lib/supabase/service";

/**
 * Listing embeddings, once per listing version, for the matcher.
 *
 * Generated by the cron with the service role (the table has no insert policy
 * for agents — a fabricated vector would quietly bias matches). The source
 * hash means a listing whose text did not change is never re-embedded, and
 * one whose text did change is. Recorded in the ledger against the listing's
 * agent, like every other call.
 */

const BATCH = 20;

export async function embedPendingListings(): Promise<Record<string, number | string>> {
  const service = createServiceClient();
  const { data: route } = await service.from("ai_models").select("*").eq("feature", "embedding").maybeSingle();
  if (!route || !route.enabled || route.provider === "none") return { skipped: "embedding route disabled" };
  const apiKey = process.env[apiKeyEnvName(route.provider as "gemini" | "anthropic")];
  if (!apiKey) return { skipped: "no provider key" };

  const { data: listings, error } = await service
    .from("listings")
    .select("id, agent_id, title, description, key_selling_points, listing_type, price, currency, properties (property_type, regency_name, district_name, bedrooms, building_size, land_size, facilities)")
    .eq("status", "published")
    .order("published_at", { ascending: false })
    .limit(200);
  if (error) return { error: error.message };

  const ids = (listings ?? []).map((l) => l.id);
  const { data: existing } = ids.length
    ? await service.from("listing_embeddings").select("listing_id, source_hash").in("listing_id", ids)
    : { data: [] as { listing_id: string; source_hash: string }[] };
  const have = new Map((existing ?? []).map((e) => [e.listing_id, e.source_hash]));

  const modelRoute: ModelRoute = {
    feature: "embedding", provider: route.provider, model: route.model, maxOutputTokens: 0,
    inputCostMicrosPer1k: route.input_cost_micros_per_1k, outputCostMicrosPer1k: route.output_cost_micros_per_1k,
  };

  let embedded = 0, unchanged = 0, failed = 0;
  for (const l of listings ?? []) {
    if (embedded + failed >= BATCH) break;
    const p = (Array.isArray(l.properties) ? l.properties[0] : l.properties) as Record<string, unknown> | null;
    const text = [
      l.title, l.description, (l.key_selling_points ?? []).join(". "),
      p?.property_type, p?.district_name, p?.regency_name,
      p?.bedrooms != null ? `${p.bedrooms} bedrooms` : null,
      p?.building_size ? `${p.building_size} sqm` : null,
      Array.isArray(p?.facilities) ? (p!.facilities as string[]).join(", ") : null,
      l.listing_type, l.price != null ? `${l.currency} ${l.price}` : null,
    ].filter(Boolean).join("\n");
    const hash = await sha256Hex(canonical({ m: route.model, text }));
    if (have.get(l.id) === hash) { unchanged++; continue; }

    const started = Date.now();
    try {
      const res = await embed({ route: modelRoute, apiKey, text, dimensions: 1536 });
      await service.from("listing_embeddings").upsert({ listing_id: l.id, embedding: JSON.stringify(res.vector), model: route.model, source_hash: hash });
      await service.rpc("ai_record_job", {
        p_user: l.agent_id, p_feature: "embedding", p_provider: route.provider, p_model: route.model, p_prompt_version: 0,
        p_status: "ok", p_denied_reason: null, p_ref_type: "listing", p_ref_id: l.id, p_input_hash: hash,
        p_tokens_in: res.usage.tokensIn, p_tokens_out: 0, p_cost_micros: res.costMicros, p_latency_ms: Date.now() - started, p_error: null,
      });
      embedded++;
    } catch (e) {
      failed++;
      await service.rpc("ai_record_job", {
        p_user: l.agent_id, p_feature: "embedding", p_provider: route.provider, p_model: route.model, p_prompt_version: 0,
        p_status: "error", p_denied_reason: null, p_ref_type: "listing", p_ref_id: l.id, p_input_hash: hash,
        p_tokens_in: 0, p_tokens_out: 0, p_cost_micros: 0, p_latency_ms: Date.now() - started,
        p_error: e instanceof Error ? e.message.slice(0, 80) : "embed failed",
      });
    }
  }
  return { candidates: listings?.length ?? 0, embedded, unchanged, failed };
}
